// Every Arcade category and game, in catalog order. Game content lives in ./games/<category>.js
// (format: ./format.js); the five demos in src/components join their category as simulations.
//
// The catalog list comes from ./catalog.index.js (ids, titles, blurbs, types, levels and round
// counts, generated by `node scripts/check-arcade.mjs`), so the Arcade shows it without loading any
// rounds. A game's rounds load when it's opened: loadGame() imports its category or extra file.
import INDEX from './catalog.index.js'
import { DEMOS } from './demos.js'

// One chunk per category file and per extra file, loaded on demand.
const content = import.meta.glob(['./games/*.js', './extra/*.js'], { import: 'default' })

const ORDER = ['limits', 'integration', 'datamodel', 'service', 'sales', 'cpq', 'deployment']

// Games of the plug-in types (./types/), each tagged with the category it belongs to.
const extras = Object.entries(INDEX)
  .filter(([src]) => src.startsWith('extra/'))
  .flatMap(([src, file]) => file.games.map((g) => ({ ...g, src })))

// Two challenges generated for every category from its quiz questions. `quiz` lists the files with
// that category's quiz games: their questions are the pool, loaded when a challenge is opened.
const challenges = (cat, quiz) => [
  { id: `${cat.id}-speed-run`, type: 'speed', level: 2, title: 'Speed run', blurb: `60 seconds, 3 lives, every ${cat.title} question. How far can your combo go?`, quiz },
  { id: `${cat.id}-hot-seat`, type: 'hotseat', level: 3, title: 'Hot seat', blurb: '10 questions from easy to brutal, two lifelines, 1,000,000 points on the line.', quiz },
]

export const CATEGORIES = ORDER.filter((id) => INDEX[`games/${id}`]).map((id) => {
  const { games: list, ...cat } = INDEX[`games/${id}`]
  const demo = DEMOS[id]
  const own = [...list.map((g) => ({ ...g, src: `games/${id}` })), ...extras.filter((g) => g.category === id)].sort((a, b) => a.level - b.level)
  const quiz = [...new Set(own.filter((g) => g.type === 'quiz').map((g) => g.src))]
  const games = [...challenges(cat, quiz), ...(demo ? [{ ...demo, type: 'demo', demo: id }] : []), ...own]
  return { ...cat, games: games.map((g) => ({ n: 0, ...g, category: id })) }
})

export const GAMES = CATEGORIES.flatMap((c) => c.games)

export const gameById = (id) => GAMES.find((g) => g.id === id)
export const categoryById = (id) => CATEGORIES.find((c) => c.id === id)

const loading = {} // promise per file
const loaded = {} // data per file, once it's in

function loadFile(src) {
  loading[src] ??= content[`./${src}.js`]?.().then((data) => {
    if (import.meta.env.DEV && data.games.map((g) => g.id).join() !== INDEX[src]?.games.map((g) => g.id).join()) {
      console.warn(`[arcade] catalog.index.js is out of date for ${src}: run node scripts/check-arcade.mjs`)
    }
    loaded[src] = data
  }) ?? Promise.reject(new Error(`no game file ${src}`))
  loading[src].catch(() => delete loading[src]) // a failed load can be retried
  return loading[src]
}

// Every quiz question of a category, tagged with its game's level: the pool for its challenges.
const quizPool = (games) => games.filter((g) => g.type === 'quiz').flatMap((g) => g.rounds.map((r) => ({ ...r, level: g.level, from: g.title })))

// A game with everything needed to play it (its rounds, or the question pool of a challenge),
// or null while its file hasn't loaded yet.
export function readyGame(game) {
  if (game.type === 'demo') return game
  if (game.quiz) {
    if (!game.quiz.every((src) => loaded[src])) return null
    const games = game.quiz.flatMap((src) => loaded[src].games.filter((g) => src.startsWith('games/') || g.category === game.category))
    return { ...game, pool: quizPool(games) }
  }
  const full = loaded[game.src]?.games.find((g) => g.id === game.id)
  return full ? { ...full, ...game, n: full.rounds?.length ?? 0 } : null
}

// The same, loading its file(s) first.
export async function loadGame(game) {
  if (game.type !== 'demo') await Promise.all((game.quiz ?? [game.src]).map(loadFile))
  const full = readyGame(game)
  if (!full) throw new Error(`${game.id} is not in ${game.src}`)
  return full
}

// The game after this one in its category, or the first game of the next category.
export function nextGame(game) {
  const i = GAMES.findIndex((g) => g.id === game.id)
  return i >= 0 ? GAMES[i + 1] ?? null : null
}
